package net.glacier.cosmetics;

import net.minecraft.resources.Identifier;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Built-in cape designs. The textures are the PNGs under assets/glacier/textures/cosmetics, generated by the
 * gen_capes script; base and accent mirror the palette used there, and drive the preview swatches in the menu.
 * Capes are client-side only: the local player sees them, other players and servers never do.
 */
public final class Capes {
	private Capes() {
	}

	public static final String NONE = "None";
	/** The cape of the Glacier set (first entry); the matching accessories are the first design of each type. */
	public static final String GLACIER_SET = "Glacier Set";
	private static final String NAMESPACE = "glacier";

	/**
	 * One cape design. {@link #texture()} is the 64x32 texture the local player wears. {@code file} names the PNG under
	 * textures/cosmetics; null means the name lowercased plus ".png".
	 */
	public record Cape(String name, int base, int accent, String file) {
		public Cape(String name, int base, int accent) {
			this(name, base, accent, null);
		}

		public String fileName() {
			return file != null ? file : name.toLowerCase(Locale.ROOT) + ".png";
		}

		/**
		 * True for capes ported from the pack: their texture keeps its native size (640x670) and is drawn by AccessoryLayer with
		 * the pack's own cape mesh, not by the vanilla cape layer, which would sample a 64x32 layout.
		 */
		public boolean pack() {
			return file != null && file.startsWith("pack/");
		}

		public Identifier texture() {
			return Identifier.fromNamespaceAndPath(NAMESPACE, "textures/cosmetics/" + fileName());
		}
	}

	public static final List<Cape> ALL = List.of(
			new Cape("Glacier Set", 0xFF7289DA, 0xFF000000, "pack/glacier_set.png"),
			new Cape("Glacier", 0xFF7289DA, 0xFFB9C6F2),
			new Cape("Midnight", 0xFF1B2140, 0xFFC9D3FF),
			new Cape("Ember", 0xFF7A1F10, 0xFFFF8A2A),
			new Cape("Moss", 0xFF2F5A2C, 0xFF6FA65E),
			new Cape("Frost", 0xFFCFE9F5, 0xFF6FB6DA),
			new Cape("Violet", 0xFF5B2F92, 0xFFA77FE0),
			new Cape("Sunset", 0xFFFF7A59, 0xFF6B2C91),
			new Cape("Mono", 0xFF1E1E1E, 0xFFE6E6E6),
			new Cape("Aurora", 0xFF1F6A67, 0xFFFFFFFF),
			new Cape("Frostbite", 0xFF9FD1E9, 0xFFE9F6FC),
			new Cape("Magma", 0xFFFF6A1A, 0xFF1A0D0A),
			new Cape("Cyber", 0xFFB4208F, 0xFF0B0F1F),
			new Cape("Sakura", 0xFFEFA7BC, 0xFFFFF0F5),
			new Cape("Ocean", 0xFF0C5F90, 0xFF7FD6FF),
			new Cape("Royal", 0xFF3A1A6B, 0xFFE8C14A),
			new Cape("Galaxy", 0xFFFFFFFF, 0xFF7A2FD0),
			new Cape("Glacier Flake", 0xFFFFFFFF, 0xFF7289DA, "glacier2.png"),
			new Cape("Checker", 0xFF101426, 0xFFCFE0FF),
			new Cape("Sunburst", 0xFFFF9A2E, 0xFFFFD35A),
			new Cape("Heart", 0xFFFF3B4E, 0xFF1E1E1E));

	/** Choice values for the cape setting: None followed by every design name. */
	public static final String[] OPTIONS = options();

	/** The design with this name, or null for None and unknown names. */
	public static Cape byName(String name) {
		for (Cape c : ALL) {
			if (c.name().equals(name)) return c;
		}
		return null;
	}

	private static String[] options() {
		List<String> names = new ArrayList<>();
		names.add(NONE);
		for (Cape c : ALL) names.add(c.name());
		return names.toArray(new String[0]);
	}
}
